cypher.cypher:
MATCH (p:LegalEntity) WHERE p.group_limit IS NOT NULL AND NOT EXISTS { (p)-[:OWNED_BY {control: true}]->() }
                         CALL (p) { MATCH (p)<-[:OWNED_BY*0.. {control: true}]-(m:LegalEntity) RETURN collect(DISTINCT m) AS ms }
                         RETURN p.id AS ultimate_parent, p.name AS name, p.group_limit AS group_limit,
                                [m IN ms | m.id] AS member_entity_ids,
                                [m IN ms WHERE m.cif_no IS NOT NULL | m.cif_no] AS member_cif_nos ORDER BY name
